/**
 * PWA glue: service worker registration and updates, the install prompt, fullscreen and the
 * portrait lock.
 *
 * The worker (dist/sw.js, generated by scripts/make-sw.mjs) is registered only in production
 * builds, and never under `?e2e` unless the URL also has `sw`, so the stepped e2e routes stay
 * deterministic. A new worker waits until the player taps RELOAD on the "new version" ticket; the
 * page then posts 'skipWaiting' and reloads once the new worker controls it.
 */

declare global {
  /** package.json version, injected by Vite `define`. */
  const __SKITCH_VERSION__: string;
  /** true in `vite build` output, false under the dev server. */
  const __SKITCH_BUILD__: boolean;
}

export function appVersion(): string {
  return typeof __SKITCH_VERSION__ === 'string' ? __SKITCH_VERSION__ : 'dev';
}

export function isProductionBuild(): boolean {
  return typeof __SKITCH_BUILD__ === 'boolean' && __SKITCH_BUILD__;
}

export interface SwPolicy {
  production: boolean;
  /** The URL has `e2e`. */
  e2e: boolean;
  /** The URL has `sw`. */
  sw: boolean;
  /** navigator.serviceWorker exists (secure context). */
  supported: boolean;
}

/** Pure: whether to register the service worker. */
export function shouldRegisterSw(p: SwPolicy): boolean {
  return p.supported && p.production && (!p.e2e || p.sw);
}

export interface Pwa {
  /** A new version is installed and waiting. */
  readonly updateReady: boolean;
  /** Activate the waiting version and reload. */
  applyUpdate(): void;
  /** The browser offered an install prompt (Android Chrome, desktop Chrome / Edge). */
  readonly installAvailable: boolean;
  /** iOS Safari, not installed: no prompt exists, show the Share hint instead. */
  readonly iosHint: boolean;
  /** Show the browser's install prompt. */
  promptInstall(): void;
  /** Ask for fullscreen and, once in it, lock portrait. Failure is ignored. */
  enterFullscreen(): void;
  /** State of the worker controlling this page, or '' (none), for tests. */
  readonly swState: string;
}

interface InstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice?: Promise<{ outcome: string }>;
}

interface LockableOrientation {
  lock?: (o: string) => Promise<void>;
}

function isIos(): boolean {
  const nav = navigator as Navigator & { standalone?: boolean };
  const ua = navigator.userAgent;
  const ios = /iPhone|iPad|iPod/i.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1);
  if (!ios) return false;
  const standalone = nav.standalone === true || window.matchMedia?.('(display-mode: standalone)').matches === true;
  return !standalone;
}

export function createPwa(opts: { e2e: boolean; sw: boolean; onChange: () => void }): Pwa {
  let waiting: ServiceWorker | null = null;
  let installEvent: InstallPromptEvent | null = null;
  let reloading = false;
  const ios = isIos();

  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    installEvent = e as InstallPromptEvent;
    opts.onChange();
  });
  window.addEventListener('appinstalled', () => {
    installEvent = null;
    opts.onChange();
  });

  const supported = typeof navigator !== 'undefined' && 'serviceWorker' in navigator;
  if (shouldRegisterSw({ production: isProductionBuild(), e2e: opts.e2e, sw: opts.sw, supported })) {
    const sw = navigator.serviceWorker;
    const track = (w: ServiceWorker | null): void => {
      if (!w) return;
      const onState = (): void => {
        if (w.state === 'installed' && sw.controller) {
          // An update: there was a controlling worker before this one.
          waiting = w;
          opts.onChange();
        }
      };
      w.addEventListener('statechange', onState);
      onState();
    };
    sw.addEventListener('controllerchange', () => {
      if (reloading || waiting === null) return;
      reloading = true;
      location.reload();
    });
    const register = (): void => {
      sw.register('./sw.js')
        .then((reg) => {
          if (reg.waiting && sw.controller) {
            waiting = reg.waiting;
            opts.onChange();
          }
          reg.addEventListener('updatefound', () => track(reg.installing));
          track(reg.installing);
          document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible') reg.update().catch(() => undefined);
          });
        })
        .catch(() => {
          /* no worker: the game still runs, only offline play is lost */
        });
    };
    if (document.readyState === 'complete') register();
    else window.addEventListener('load', register, { once: true });
  }

  return {
    get updateReady() {
      return waiting !== null;
    },
    applyUpdate() {
      const w = waiting;
      if (!w) return;
      w.postMessage('skipWaiting');
    },
    get installAvailable() {
      return installEvent !== null;
    },
    get iosHint() {
      return ios && installEvent === null;
    },
    promptInstall() {
      const ev = installEvent;
      if (!ev) return;
      installEvent = null;
      ev.prompt().catch(() => undefined);
      opts.onChange();
    },
    enterFullscreen() {
      const lock = (): void => {
        const o = screen.orientation as ScreenOrientation & LockableOrientation;
        if (o && typeof o.lock === 'function') o.lock('portrait').catch(() => undefined);
      };
      try {
        const root = document.documentElement;
        if (document.fullscreenElement || typeof root.requestFullscreen !== 'function') {
          lock();
          return;
        }
        root.requestFullscreen({ navigationUI: 'hide' }).then(lock, () => undefined);
      } catch (_e) {
        /* fullscreen refused: play in the browser */
      }
    },
    get swState() {
      return supported ? (navigator.serviceWorker.controller?.state ?? '') : '';
    },
  };
}
